import urllib.request

BASE='https://raw.githubusercontent.com/namelessdhamma/namelessdhamma.github.io/23b4b0e95652355f3e8a01473fe944e899c87ace/tmp/nd_vk_gateway_v17_omniroute_reserve.py'
outer=urllib.request.urlopen(BASE,timeout=30).read().decode('utf-8')

marker='inject="v17_patch_code="+repr(v17_patch_code)'
if outer.count(marker)!=1:
    raise RuntimeError('V18 V17 injection marker mismatch count=%d' % outer.count(marker))

v18_patch_code='\n# V18: provider expansion + safer circuit breaking. Keeps V17 routing semantics.\n_env_marker="OMNIROUTE_MODEL=os.environ.get(\'OMNIROUTE_MODEL\',\'glm/glm-4.7-flash\').strip() or \'glm/glm-4.7-flash\'\\n"\n_env_new=_env_marker+(\n    "CEREBRAS_API_KEY=os.environ.get(\'CEREBRAS_API_KEY\',\'\').strip()\\n"\n    "CEREBRAS_MODEL=os.environ.get(\'CEREBRAS_MODEL\',\'gpt-oss-120b\').strip() or \'gpt-oss-120b\'\\n"\n    "CLOUDFLARE_ACCOUNT_ID=os.environ.get(\'CLOUDFLARE_ACCOUNT_ID\',\'\').strip()\\n"\n    "CLOUDFLARE_API_TOKEN=os.environ.get(\'CLOUDFLARE_API_TOKEN\',\'\').strip()\\n"\n    "CLOUDFLARE_MODEL=os.environ.get(\'CLOUDFLARE_MODEL\',\'@cf/openai/gpt-oss-120b\').strip() or \'@cf/openai/gpt-oss-120b\'\\n"\n)\nif _env_marker not in src:\n    raise RuntimeError(\'V18 provider env marker missing\')\nsrc=src.replace(_env_marker,_env_new,1)\n\n_redact_old="for secret in (TOKEN,GROQ_API_KEY,OPENROUTER_API_KEY,PATH_KEY):"\n_redact_new="for secret in (TOKEN,GROQ_API_KEY,OPENROUTER_API_KEY,MISTRAL_API_KEY,OPENAI_API_KEY,ZAI_API_KEY,CEREBRAS_API_KEY,CLOUDFLARE_API_TOKEN,PATH_KEY):"\nif _redact_old not in src:\n    raise RuntimeError(\'V18 cleanerr marker missing\')\nsrc=src.replace(_redact_old,_redact_new,1)\n\n_cooldown_old="""    if \'free-models-per-day\' in s:\n        cooldown=21600\n    elif \'429\' in s or \'rate limit\' in s or \'tokens per day\' in s:\n        cooldown=3600\n    elif \'http 5\' in s or \'timed out\' in s or \'timeout\' in s:\n        cooldown=120\n    else:\n        cooldown=30\n"""\n_cooldown_new="""    _m=re.search(r\'reset after\\s*(\\d+)\\s*s\',s)\n    if _m:\n        cooldown=max(5,min(300,int(_m.group(1))+2))\n    elif \'insufficient quota\' in s or \'insufficient balance\' in s or \'credit_balance_exhausted\' in s or \'no credits remaining\' in s:\n        cooldown=21600\n    elif \'free-models-per-day\' in s:\n        cooldown=21600\n    elif \'429\' in s or \'rate limit\' in s or \'tokens per day\' in s:\n        cooldown=900\n    elif \'http 5\' in s or \'timed out\' in s or \'timeout\' in s:\n        cooldown=120\n    else:\n        cooldown=30\n"""\nif _cooldown_old not in src:\n    raise RuntimeError(\'V18 cooldown marker missing\')\nsrc=src.replace(_cooldown_old,_cooldown_new,1)\n\n_provider_funcs="""def cerebras_chat(messages,max_tokens=3000,temperature=0.35):\n    if not CEREBRAS_API_KEY:\n        raise RuntimeError(\'CEREBRAS_API_KEY missing\')\n    if _provider_blocked(\'cerebras\'):\n        raise RuntimeError(\'Cerebras circuit open\')\n    payload={\'model\':CEREBRAS_MODEL,\'messages\':messages,\'max_completion_tokens\':max_tokens,\'temperature\':temperature}\n    try:\n        j=http_json(\'https://api.cerebras.ai/v1/chat/completions\',payload,CEREBRAS_API_KEY,180)\n        _provider_success(\'cerebras\')\n    except Exception as e:\n        _provider_fail(\'cerebras\',e); raise\n    ch=j.get(\'choices\') or []\n    if not ch:\n        raise RuntimeError(\'Cerebras returned no choices\')\n    out=((ch[0].get(\'message\') or {}).get(\'content\') or \'\').strip()\n    if not out:\n        raise RuntimeError(\'Cerebras returned empty content\')\n    state[\'last_reserve_provider\']=\'cerebras:\'+CEREBRAS_MODEL\n    print(\'AI_RESERVE_PROVIDER\',json.dumps({\'provider\':\'cerebras\',\'model\':CEREBRAS_MODEL},ensure_ascii=False),flush=True)\n    return out\n\ndef cloudflare_chat(messages,max_tokens=3000,temperature=0.35):\n    if not CLOUDFLARE_ACCOUNT_ID or not CLOUDFLARE_API_TOKEN:\n        raise RuntimeError(\'Cloudflare credentials missing\')\n    if _provider_blocked(\'cloudflare\'):\n        raise RuntimeError(\'Cloudflare circuit open\')\n    payload={\'model\':CLOUDFLARE_MODEL,\'messages\':messages,\'max_tokens\':max_tokens,\'temperature\':temperature,\'options\':{\'rejectIfBusy\':True}}\n    url=\'https://api.cloudflare.com/client/v4/accounts/\'+CLOUDFLARE_ACCOUNT_ID+\'/ai/v1/chat/completions\'\n    try:\n        j=http_json(url,payload,CLOUDFLARE_API_TOKEN,180)\n        _provider_success(\'cloudflare\')\n    except Exception as e:\n        _provider_fail(\'cloudflare\',e); raise\n    ch=j.get(\'choices\') or []\n    if not ch:\n        raise RuntimeError(\'Cloudflare returned no choices\')\n    out=((ch[0].get(\'message\') or {}).get(\'content\') or \'\').strip()\n    if not out:\n        raise RuntimeError(\'Cloudflare returned empty content\')\n    state[\'last_reserve_provider\']=\'cloudflare:\'+CLOUDFLARE_MODEL\n    print(\'AI_RESERVE_PROVIDER\',json.dumps({\'provider\':\'cloudflare\',\'model\':CLOUDFLARE_MODEL},ensure_ascii=False),flush=True)\n    return out\n\n"""\n_reserve_marker="def reserve_chat(messages,max_tokens=3000,temperature=0.35):\\n    errs=[]\\n"\n_reserve_new="""def reserve_chat(messages,max_tokens=3000,temperature=0.35):\n    errs=[]\n    if CEREBRAS_API_KEY:\n        try: return cerebras_chat(messages,max_tokens=max_tokens,temperature=temperature)\n        except Exception as e:\n            errs.append(\'cerebras:\'+cleanerr(e))\n            print(\'CEREBRAS_RESERVE_ERROR\',cleanerr(e),flush=True)\n    if CLOUDFLARE_ACCOUNT_ID and CLOUDFLARE_API_TOKEN:\n        try: return cloudflare_chat(messages,max_tokens=max_tokens,temperature=temperature)\n        except Exception as e:\n            errs.append(\'cloudflare:\'+cleanerr(e))\n            print(\'CLOUDFLARE_RESERVE_ERROR\',cleanerr(e),flush=True)\n"""\nif _reserve_marker not in src:\n    raise RuntimeError(\'V18 reserve marker missing\')\nsrc=src.replace(_reserve_marker,_provider_funcs+_reserve_new,1)\n\n_groq_required="if not GROQ_API_KEY:raise RuntimeError(\'GROQ_API_KEY missing\')"\n_groq_optional="if not GROQ_API_KEY:return reserve_chat(messages,max_tokens=max_tokens)"\nif _groq_required not in src:\n    raise RuntimeError(\'V18 groq required marker missing\')\nsrc=src.replace(_groq_required,_groq_optional,1)\n\n_gate_old="                if not GROQ_API_KEY:send(peer,\'AI-контур временно недоступен: GROQ_API_KEY не настроен.\');return"\n_gate_new="                if not any((GROQ_API_KEY,OPENROUTER_API_KEY,MISTRAL_API_KEY,OPENAI_API_KEY,ZAI_API_KEY,OMNIROUTE_BASE_URL,CEREBRAS_API_KEY,(CLOUDFLARE_ACCOUNT_ID and CLOUDFLARE_API_TOKEN))):send(peer,\'AI-контур временно недоступен: нет настроенных провайдеров.\');return"\nif _gate_old not in src:\n    raise RuntimeError(\'V18 provider gate marker missing\')\nsrc=src.replace(_gate_old,_gate_new,1)\n\n_probe_tail="""            else:\n                state[\'omniroute_probe\']=\'not_configured\'\n            return\n"""\n_probe_new="""            else:\n                state[\'omniroute_probe\']=\'not_configured\'\n            if CEREBRAS_API_KEY:\n                try:\n                    out=cerebras_chat([{\'role\':\'user\',\'content\':\'Reply exactly OK.\'}],64,0.0)\n                    state[\'cerebras_probe\']=\'ok\' if out else \'empty\'\n                    print(\'CEREBRAS_PROBE_OK\',flush=True)\n                except Exception as e:\n                    state[\'cerebras_probe\']=\'error\'\n                    print(\'CEREBRAS_PROBE_ERROR\',cleanerr(e),flush=True)\n            else:\n                state[\'cerebras_probe\']=\'not_configured\'\n            if CLOUDFLARE_ACCOUNT_ID and CLOUDFLARE_API_TOKEN:\n                try:\n                    out=cloudflare_chat([{\'role\':\'user\',\'content\':\'Reply exactly OK.\'}],64,0.0)\n                    state[\'cloudflare_probe\']=\'ok\' if out else \'empty\'\n                    print(\'CLOUDFLARE_PROBE_OK\',flush=True)\n                except Exception as e:\n                    state[\'cloudflare_probe\']=\'error\'\n                    print(\'CLOUDFLARE_PROBE_ERROR\',cleanerr(e),flush=True)\n            else:\n                state[\'cloudflare_probe\']=\'not_configured\'\n            return\n"""\nif _probe_tail not in src:\n    raise RuntimeError(\'V18 startup probe marker missing\')\nsrc=src.replace(_probe_tail,_probe_new,1)\n'
inject="v18_patch_code="+repr(v18_patch_code)+"\nv17_patch_code += '\\n'+v18_patch_code\n"
outer=outer.replace(marker,inject+marker,1)

print('ND_V18_PROVIDER_EXPANSION_WRAPPER_READY',flush=True)
exec(compile(outer,'nd_vk_gateway_v18_provider_expansion.py','exec'))
